<template>
  <main class="public-result">
    <header class="topbar"><RouterLink class="brand" to="/"><span>S</span><div><b>School ERP</b><small>Online Result Service</small></div></RouterLink><RouterLink class="login" to="/login">Staff login</RouterLink></header>
    <section class="lookup no-print">
      <div class="intro"><span>ONLINE RESULT</span><h1>পরীক্ষার ফলাফল দেখুন</h1><p>Published examination নির্বাচন করে Student ID দিয়ে নিরাপদে ফলাফল দেখুন।</p></div>
      <form class="search-card" @submit.prevent="findResult">
        <label>Examination<select v-model="examId" required><option value="">Select published exam</option><option v-for="exam in exams" :key="exam.exam_id" :value="exam.exam_id">{{ exam.exam_name }} — {{ exam.class_name || 'All classes' }} · {{ exam.year_name || '' }}</option></select></label>
        <label>Student ID / শিক্ষার্থী আইডি<input v-model.trim="studentNo" required autocomplete="off" placeholder="e.g. STU-0001" /></label>
        <button :disabled="loading">{{ loading ? 'Searching…' : 'View result' }}</button>
      </form>
      <p v-if="message" class="message">{{ message }}</p>
    </section>

    <section v-if="result" class="result-sheet">
      <div class="watermark">RESULT</div>
      <header class="sheet-head"><div class="school-mark">S</div><div><h2>{{ institution.institution_name || 'Educational Institution' }}</h2><p>{{ institution.address || institution.institution_address || 'Academic Result Publication' }}</p><h3>{{ exam.exam_name }}</h3><small>{{ exam.class_name }} · {{ exam.year_name }}</small></div><span class="verified">✓ Published</span></header>
      <section class="identity"><div><span>Student name</span><b>{{ student.full_name }}</b></div><div><span>Student ID</span><b>{{ student.student_no }}</b></div><div><span>Class</span><b>{{ exam.class_name || student.class_name || '—' }}</b></div><div><span>Roll / Candidate</span><b>{{ student.roll_no || student.candidate_no || '—' }}</b></div></section>
      <div class="table-wrap"><table><thead><tr><th>Subject</th><th>Full marks</th><th>Pass marks</th><th>Obtained</th><th>Grade</th><th>Status</th></tr></thead><tbody><tr v-for="line in lines" :key="line.result_detail_id || `${line.subject_id}-${line.paper_no}`"><td><b>{{ line.subject_name }}{{ paperLabel(line.paper_no) }}</b><small>{{ line.subject_name_bn || line.subject_code }}{{ paperLabelBn(line.paper_no) }}</small></td><td>{{ line.full_marks }}</td><td>{{ line.pass_marks }}</td><td><b>{{ line.obtained_marks }}</b></td><td>{{ line.letter_grade }} <small>GP {{ line.grade_point }}</small></td><td><span class="subject-status" :class="String(line.subject_status).toLowerCase()">{{ line.subject_status }}</span></td></tr></tbody></table></div>
      <section class="result-summary"><div><span>Total marks</span><b>{{ result.obtained_marks }} / {{ result.total_marks }}</b></div><div><span>GPA</span><b>{{ Number(result.gpa || 0).toFixed(2) }}</b></div><div><span>Letter grade</span><b>{{ result.letter_grade || '—' }}</b></div><div><span>Merit position</span><b>{{ result.merit_position || '—' }}</b></div><div class="overall"><span>Overall result</span><b :class="String(result.result_status).toLowerCase()">{{ result.result_status }}</b></div></section>
      <footer><p>This result was published online by the institution. Generated {{ printedAt }}.</p><button class="no-print" @click="printResult">Print result</button></footer>
    </section>
  </main>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue';
import api from '../../services/api';

const exams = ref([]), examId = ref(''), studentNo = ref(''), payload = ref(null), loading = ref(false), message = ref('');
const paperLabel = (value) => Number(value) === 1 ? ' — 1st Paper' : Number(value) === 2 ? ' — 2nd Paper' : '';
const paperLabelBn = (value) => Number(value) === 1 ? ' · ১ম পত্র' : Number(value) === 2 ? ' · ২য় পত্র' : '';
const result = computed(() => payload.value?.result || payload.value?.student_result || payload.value || null);
const student = computed(() => payload.value?.student || result.value || {});
const exam = computed(() => payload.value?.exam || exams.value.find((item) => String(item.exam_id) === String(examId.value)) || {});
const institution = computed(() => payload.value?.institution || result.value || {});
const lines = computed(() => payload.value?.subjects || payload.value?.details || payload.value?.result_details || []);
const printedAt = computed(() => new Intl.DateTimeFormat('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }).format(new Date()).toUpperCase());
async function findResult() { try { loading.value = true; message.value = ''; payload.value = null; const response = await api.get('/exams/public/results', { params: { exam_id: examId.value, student_no: studentNo.value } }); payload.value = response.data.data; } catch (error) { message.value = error.response?.data?.message || 'Published result পাওয়া যায়নি। তথ্য যাচাই করে আবার চেষ্টা করুন।'; } finally { loading.value = false; } }
function printResult() { window.print(); }
onMounted(async () => { try { exams.value = (await api.get('/exams/public/exams')).data.data || []; } catch { exams.value = []; } });
</script>

<style scoped>
.public-result{min-height:100vh;background:radial-gradient(circle at 20% 0,#dbeafe 0,transparent 34%),#f4f7fb;color:#172033;font-family:Inter,"Noto Sans Bengali",system-ui,sans-serif}.topbar{display:flex;align-items:center;justify-content:space-between;max-width:1120px;margin:auto;padding:22px}.brand{display:flex;align-items:center;gap:10px;color:#172033;text-decoration:none}.brand>span,.school-mark{display:grid;width:42px;height:42px;place-items:center;border-radius:13px;background:#2563eb;color:#fff;font-size:20px;font-weight:900}.brand b,.brand small{display:block}.brand small{margin-top:2px;color:#64748b;font-size:11px}.login{padding:8px 11px;border:1px solid #cbd5e1;border-radius:9px;background:#fff;color:#334155;font-size:12px;font-weight:800;text-decoration:none}.lookup{display:grid;grid-template-columns:1fr 1fr;gap:38px;align-items:center;max-width:960px;margin:50px auto;padding:0 22px}.intro>span{color:#2563eb;font-size:10px;font-weight:900;letter-spacing:.14em}.intro h1{margin:8px 0;font-size:38px;letter-spacing:-.04em}.intro p{max-width:520px;margin:0;color:#64748b;line-height:1.7}.search-card{display:grid;gap:14px;padding:24px;border:1px solid #dfe7f2;border-radius:20px;background:#fff;box-shadow:0 22px 50px rgba(37,99,235,.1)}.search-card label{display:grid;gap:7px;color:#334155;font-size:12px;font-weight:800}.search-card input,.search-card select{height:48px;padding:0 12px;border:1px solid #cbd5e1;border-radius:10px;background:#fff;font:inherit}.search-card button,.result-sheet footer button{padding:12px;border:0;border-radius:10px;background:#2563eb;color:#fff;font:inherit;font-weight:850;cursor:pointer}.message{grid-column:1/-1;margin:0;padding:12px;border-radius:10px;background:#fee2e2;color:#b91c1c;font-size:13px;font-weight:700;text-align:center}.result-sheet{position:relative;max-width:960px;margin:0 auto 60px;padding:32px;border:1px solid #dbe3ef;border-radius:20px;background:#fff;box-shadow:0 22px 55px rgba(15,23,42,.1);overflow:hidden}.watermark{position:absolute;top:45%;left:50%;color:#2563eb;font-size:110px;font-weight:900;letter-spacing:.12em;opacity:.025;transform:translate(-50%,-50%) rotate(-22deg)}.sheet-head{position:relative;display:flex;align-items:flex-start;gap:15px;padding-bottom:22px;border-bottom:2px solid #2563eb;text-align:center}.sheet-head>div:nth-child(2){flex:1}.sheet-head h2{margin:0;font-size:24px}.sheet-head p,.sheet-head h3{margin:5px 0}.sheet-head p,.sheet-head small{color:#64748b}.verified{padding:5px 8px;border-radius:99px;background:#dcfce7;color:#166534;font-size:10px;font-weight:900}.identity{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin:20px 0}.identity div,.result-summary div{padding:12px;border-radius:10px;background:#f8fafc}.identity span,.identity b,.result-summary span,.result-summary b{display:block}.identity span,.result-summary span{color:#64748b;font-size:10px}.identity b,.result-summary b{margin-top:5px;font-size:13px}.table-wrap{overflow:auto;border:1px solid #e3eaf4;border-radius:12px}table{width:100%;border-collapse:collapse}th,td{padding:11px;border-bottom:1px solid #e5eaf3;text-align:left;font-size:12px}th{background:#eff6ff;color:#1e40af;font-size:9px;text-transform:uppercase}td b,td small{display:block}td small{margin-top:3px;color:#64748b}.subject-status{font-size:10px;font-weight:900}.subject-status.passed{color:#047857}.subject-status.failed,.subject-status.absent{color:#be123c}.result-summary{display:grid;grid-template-columns:repeat(5,1fr);gap:9px;margin-top:18px}.result-summary .overall{background:#eff6ff}.overall b.passed{color:#047857}.overall b.failed,.overall b.absent{color:#be123c}.result-sheet footer{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-top:22px;padding-top:16px;border-top:1px solid #e5eaf3}.result-sheet footer p{margin:0;color:#64748b;font-size:10px}@media(max-width:760px){.lookup{grid-template-columns:1fr;margin:25px auto}.intro h1{font-size:31px}.result-sheet{margin:0 14px 35px;padding:18px}.identity,.result-summary{grid-template-columns:1fr 1fr}.sheet-head{flex-wrap:wrap}.verified{margin-left:auto}}@media print{.no-print,.topbar{display:none!important}.public-result{background:#fff}.result-sheet{max-width:none;margin:0;padding:12mm;border:0;border-radius:0;box-shadow:none}.watermark{opacity:.025}.sheet-head h2{font-size:21px}.result-sheet footer{margin-top:16px}}
</style>
